package pe.cruzroja.convocatorias.callouts.domain; import java.time.*; import java.util.UUID; import pe.cruzroja.convocatorias.users.domain.TrainingLevel; public class Callout {private final UUID id; private final String title,description,location,requirements; private final LocalDateTime start,end; private final TrainingLevel minimumLevel; private final int capacity,minimum; private CalloutStatus status=CalloutStatus.BORRADOR; public Callout(UUID id,String title,String description,LocalDateTime start,LocalDateTime end,String location,String requirements,TrainingLevel level,int capacity,int minimum){if(id==null||title==null||title.isBlank()||start==null||end==null||!end.isAfter(start)||capacity<=0||minimum<1||minimum>capacity)throw new IllegalArgumentException("Datos de convocatoria inválidos");this.id=id;this.title=title;this.description=description;this.start=start;this.end=end;this.location=location;this.requirements=requirements;this.minimumLevel=level;this.capacity=capacity;this.minimum=minimum;} public void publish(){if(status!=CalloutStatus.BORRADOR)throw new IllegalStateException("Solo se publica desde borrador");status=CalloutStatus.PUBLICADA;} public void confirm(int enrolled){if(status!=CalloutStatus.PUBLICADA||enrolled<minimum)throw new IllegalStateException("No se alcanzó el mínimo de participantes");status=CalloutStatus.CONFIRMADA;} public void cancel(){if(status==CalloutStatus.FINALIZADA||status==CalloutStatus.CANCELADA)throw new IllegalStateException("La convocatoria ya es final");status=CalloutStatus.CANCELADA;} public boolean isCompatibleWith(TrainingLevel level){return level!=null&&level.ordinal()>=minimumLevel.ordinal();} public UUID id(){return id;} public String title(){return title;} public String description(){return description;} public LocalDateTime start(){return start;} public LocalDateTime end(){return end;} public String location(){return location;} public String requirements(){return requirements;} public TrainingLevel minimumLevel(){return minimumLevel;} public int capacity(){return capacity;} public int minimum(){return minimum;} public CalloutStatus status(){return status;} }
